import os
from pathlib import Path
from playwright.sync_api import sync_playwright
import json,re
root=Path(__file__).resolve().parents[1]
def flatten(p):
 s=re.sub(r'\bimport\s*\{[^}]+\}\s*from\s*[^;]+;','',p.read_text());s=re.sub(r'export\s*\{[^}]+\};','',s);return s.replace('export ','')
# No actual navigations or merchant interaction. Mock storage, lock and hash only in UI test;
# native SHA-256 semantics exercised by Node tests.
mock="""(()=>{const m=new Map();Object.defineProperty(window,'localStorage',{configurable:true,value:{getItem:k=>m.get(k)??null,setItem:(k,v)=>m.set(k,String(v)),removeItem:k=>m.delete(k)}});Object.defineProperty(navigator,'locks',{configurable:true,value:{request:async(k,f)=>f()}});if(!crypto.randomUUID)Object.defineProperty(crypto,'randomUUID',{value:()=> '44444444-4444-4444-8444-444444444444'});if(!crypto.subtle)Object.defineProperty(crypto,'subtle',{value:{digest:async(_,bytes)=>{const out=new Uint8Array(32);for(let i=0;i<bytes.length;i++)out[i%32]=(out[i%32]+bytes[i]+i)%256;return out.buffer;}}});})()"""
results=[]
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
 for mode in ['gc-wallet-companion','site','embedded']:
  d=root/('gc-wallet-companion' if mode=='embedded' else mode);page=b.new_page(viewport={'width':340 if mode=='embedded' else 412,'height':600 if mode=='embedded' else 923});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.route('**/*',lambda route:route.abort());html=(d/('overlay.html' if mode=='embedded' else 'manual.html')).read_text().replace('<main hidden inert class=','<main class=').replace('<script type="module" src="overlay-entry.js"></script>','').replace('<link rel="stylesheet" href="style.css">','<style>'+(d/'style.css').read_text()+'</style>').replace('<script type="module" src="manual.js"></script>','');page.set_content(html);page.add_script_tag(content=mock);page.add_script_tag(content='(()=>{'+ '\n'.join(flatten(d/n) for n in ['wire.js','protocol.js','session.js','manual-session.js','manual-acceptance.js','batch-policy.js','manual.js'])+'})()');
  if mode!='embedded':
   page.get_by_text('Acceptance test',exact=True).click();page.locator('#self').click();page.wait_for_function("document.querySelector('#testStatus').textContent.startsWith('PASS')",timeout=5000)
   with page.expect_download() as dl:page.locator('#report').click()
   report=json.loads(Path(dl.value.path()).read_text());assert report['complete'] and len(report['checks'])==9
  assert page.locator('#input').is_visible();assert page.locator('#reviewProgress').evaluate('(e)=>e.value')==0;page.locator('#input').fill('WMGC-REQUEST\t1\nref\tcardNumber\tpin\n11111111-1111-4111-8111-111111111111\t0000000000001111\t0001');page.locator('#import').click();page.wait_for_function("document.querySelector('#status').textContent.includes('1 added')");assert not page.locator('#input').input_value();page.locator('#start').click();assert page.locator('#number').get_attribute('type')=='password';page.evaluate("Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async()=>{throw Error('blocked')}}})");page.locator('#copyNumber').click();page.wait_for_function("document.querySelector('#status').textContent.includes('Clipboard unavailable')");assert page.locator('#number').evaluate('(e)=>e.selectionStart===0&&e.selectionEnd===16');page.evaluate("window.copied=[];Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async v=>copied.push(v)}})");page.locator('#copyPin').click();page.wait_for_function("document.querySelector('#status').textContent.includes('PIN copied')");assert page.evaluate("copied.length===1&&copied[0]==='0001'");assert page.locator('#pin').input_value()=='0001';page.locator('#amount').fill('0');assert page.locator('#save').is_disabled();page.locator('#confirmed').check();page.locator('#save').click();page.wait_for_function("document.querySelector('#progress').textContent.includes('1/1 completed')");assert page.locator('#pin').input_value()=='';assert page.locator('#reviewProgress').evaluate('(e)=>e.value===1&&e.max===1');page.locator('#resultsTab').click();page.locator('#wallet').click();page.wait_for_function("document.querySelector('#status').textContent.includes('Wallet results copied')");assert '\t0.00\t' in page.locator('#output').input_value();assert page.evaluate("copied.length===2&&copied[1].startsWith('WMGC-RESULT')&&!copied[1].includes('0000000000001111')");page.evaluate("Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async()=>{throw Error('blocked')}}})");page.locator('#legacy').click();page.wait_for_function("document.querySelector('#status').textContent.includes('Ctrl+C')");assert page.locator('#output').evaluate('(e)=>e.selectionStart===0&&e.selectionEnd===e.value.length');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.set_viewport_size({'width':1100,'height':923});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.locator('#denied').click();assert page.locator('#start').is_disabled();assert not errors,errors;results.append({'distribution':mode,'checks':report['checks'],'manual_ui':'pass','progress_and_explicit_copy':'pass','mobile':True,'desktop':True,'scope':'Chromium UI, mocked storage, locks and hash when unavailable; no merchant requests'});page.close()
 b.close()
(root/'tests/manual-browser-results.json').write_text(json.dumps(results,indent=2)+'\n');print('Both manual distributions and embedded layout passed mock browser UI and acceptance')
